<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage3; class ctfile extends cloudStorage3 { var $session; private $restBase = 'https://rest.ctfile.com'; public function init() { $this->custom_upload_dir = $this->options->cloud_storage_ctfile_custom_upload_dir; $this->folder = $this->options->cloud_storage_ctfile_folder; $this->session = $this->options->cloud_storage_ctfile_session; $this->sync_delete = $this->options->cloud_storage_ctfile_sync_delete; $this->silent_scanning = $this->options->cloud_storage_ctfile_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_ctfile_delete_attachment_after_synced; } public function access_service() { if ($this->enabled && $this->is_current && !$this->accessed) { if ($this->session) { $data = $this->listFolder(); if ($data) $this->accessed = true; } } } private function listFolder(string $folderId = 'd0', int $start = 0, string $orderby = 'new'): array { $url = $this->restBase . '/v1/public/file/list'; $payload = [ 'session' => $this->session, 'folder_id' => $folderId, 'start' => $start, 'orderby' => $orderby ]; $ch = curl_init($url); curl_setopt_array($ch, [ CURLOPT_POST => true, CURLOPT_HTTPHEADER => ['Content-Type: application/json'], CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_UNICODE), CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 30, ]); $resp = curl_exec($ch); if ($resp === false) { $err = curl_error($ch); curl_close($ch); return array(); } curl_close($ch); $data = json_decode($resp, true); if (!is_array($data)) { return array(); } return $data; } private function calcChecksum(string $filePath): string { $size = filesize($filePath); $md5 = md5_file($filePath); return $md5 . '-' . $size; } public function getUploadUrl(string $folderId, string $filePath, ?string $customName = null): array { if (!is_file($filePath)) { do_action( 'qqworld-collector-log', $this->log_id, 'ctfile source file not exists:', $filePath ); return false; } $size = filesize($filePath); $name = $customName ?: basename($filePath); $checksum = $this->calcChecksum($filePath); $payload = [ 'session' => $this->session, 'folder_id' => $folderId, 'checksum' => $checksum, 'size' => (string)$size, 'name' => $name, ]; $url = $this->restBase . '/v1/public/file/upload'; $ch = curl_init($url); curl_setopt_array($ch, [ CURLOPT_POST => true, CURLOPT_HTTPHEADER => ['Content-Type: application/json'], CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_UNICODE), CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 30, ]); $resp = curl_exec($ch); if ($resp === false) { $err = curl_error($ch); curl_close($ch); throw new RuntimeException("»ñÈ¡ upload_url Ê§°Ü: $err"); } $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch); $data = json_decode($resp, true); if ($httpCode !== 200 || !is_array($data) || !isset($data['code'])) { do_action( 'qqworld-collector-log', $this->log_id, 'ctfile upload return failed:', "HTTP $httpCode, original return: $resp" ); return false; } if ((int)$data['code'] !== 200) { $msg = $data['message'] ?? 'Unknown error'; do_action( 'qqworld-collector-log', $this->log_id, 'ctfile upload failed:', "code = {$data['code']}, message = $msg" ); return false; } return [ 'exists' => (int)($data['exists'] ?? 0), 'upload_url' => (string)($data['upload_url'] ?? ''), 'name' => $name, 'size' => $size, ]; } public function uploadToUploadUrl(string $uploadUrl, string $filePath, string $name, int $size): array { if (!is_file($filePath)) { do_action( 'qqworld-collector-log', $this->log_id, 'ctfile source file not exists:', $filePath ); return false; } $postFields = [ 'name' => $name, 'filesize' => $size, 'file' => new \CURLFile($filePath, mime_content_type($filePath) ?: 'application/octet-stream', $name), ]; $ch = curl_init($uploadUrl); curl_setopt_array($ch, [ CURLOPT_POST => true, CURLOPT_POSTFIELDS => $postFields, CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 600, ]); $resp = curl_exec($ch); if ($resp === false) { $err = curl_error($ch); curl_close($ch); do_action( 'qqworld-collector-log', $this->log_id, 'ctfile upload failed:', $err ); return false; } $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch); $data = json_decode($resp, true); if ($httpCode !== 200 || !is_array($data) || !isset($data['code'])) { do_action( 'qqworld-collector-log', $this->log_id, 'ctfile upload return failed:', "HTTP $httpCode, original return: $resp" ); return false; } if ((int)$data['code'] !== 200) { $msg = $data['message'] ?? 'Unknown error'; do_action( 'qqworld-collector-log', $this->log_id, 'ctfile upload failed:', "code = {$data['code']}, message = $msg" ); return false; } return $data; } public function getShareLinks(array $ids) { $url = $this->restBase . '/v1/public/file/share'; $payload = [ 'session' => $this->session, 'ids' => $ids ]; $ch = curl_init($url); curl_setopt_array($ch, [ CURLOPT_POST => true, CURLOPT_HTTPHEADER => ['Content-Type: application/json'], CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_UNICODE), CURLOPT_RETURNTRANSFER => true ]); $resp = curl_exec($ch); if ($resp === false) { do_action( 'qqworld-collector-log', $this->log_id, 'ctfile upload get share faile:', curl_error($ch) ); return false; } curl_close($ch); $data = json_decode($resp, true); return $data; } private function resolveFolderIdByPath(array $folders, string $rootId = 'd0'): ?string { $currentId = $rootId; foreach ($folders as $name) { $name = trim($name); if ($name === '') continue; $list = $this->listFolder($currentId); $nextId = null; if (!empty($list['results']) && is_array($list['results'])) { foreach ($list['results'] as $item) { if (($item['icon'] ?? '') === 'folder' && ($item['name'] ?? '') === $name) { $nextId = $item['key'] ?? null; break; } } } if ($nextId === null) { return null; } $currentId = $nextId; } return $currentId; } private function fileExistsInFolder(string $folderId, string $fileName): bool { $start = 0; $pageSize = 50; while (true) { $list = $this->listFolder($folderId, $start); if (!isset($list['results']) || !is_array($list['results'])) { return false; } foreach ($list['results'] as $item) { if (($item['icon'] ?? '') !== 'folder' && ($item['name'] ?? '') === $fileName) { return true; } } if (count($list['results']) < $pageSize) { return false; } $start += $pageSize; } } private function getFolderList(string $folderId) { $url = $this->restBase . '/v1/public/folder/list'; $payload = [ 'session' => $this->session, 'folder_id' => $folderId, 'start' => 0, 'orderby' => 'new', 'reload' => 0 ]; $ch = curl_init($url); curl_setopt_array($ch, [ CURLOPT_POST => true, CURLOPT_HTTPHEADER => ['Content-Type: application/json'], CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_UNICODE), CURLOPT_RETURNTRANSFER => true ]); $resp = curl_exec($ch); curl_close($ch); $data = json_decode($resp, true); return $data['results'] ?? []; } private function createFolder(string $parentId, string $name) { $url = $this->restBase . '/v1/public/folder/create'; $payload = [ 'session' => $this->session, 'folder_id' => $parentId, 'name' => $name, 'is_hidden' => 0 ]; $ch = curl_init($url); curl_setopt_array($ch, [ CURLOPT_POST => true, CURLOPT_HTTPHEADER => ['Content-Type: application/json'], CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_UNICODE), CURLOPT_RETURNTRANSFER => true ]); $resp = curl_exec($ch); curl_close($ch); $data = json_decode($resp, true); if (isset($data['code']) && $data['code'] == 200) { return $data['key']; } do_action( 'qqworld-collector-log', $this->log_id, 'ctfile make dir failed:', ($data['message'] ?? 'Unknown error') ); } public function createPath(string $path, string $rootId = 'd0') { $parts = explode('/', trim($path, '/')); $currentId = $rootId; foreach ($parts as $part) { $exists = false; $folders = $this->getFolderList($currentId); foreach ($folders as $folder) { if ($folder['name'] === $part) { $currentId = $folder['key']; $exists = true; break; } } if (!$exists) { $currentId = $this->createFolder($currentId, $part); } } return $currentId; } public function deleteToRecycle(array $ids) { return $this->post('/v1/public/file/delete', [ 'session' => $this->session, 'ids' => $ids ]); } public function clearRecycleByIds(array $ids) { return $this->post('/v1/public/file/recycle_empty', [ 'session' => $this->session, 'ids' => $ids ]); } private function post(string $path, array $payload) { $url = $this->restBase . $path; $ch = curl_init($url); curl_setopt_array($ch, [ CURLOPT_POST => true, CURLOPT_HTTPHEADER => ['Content-Type: application/json'], CURLOPT_POSTFIELDS => json_encode($payload, JSON_UNESCAPED_UNICODE), CURLOPT_RETURNTRANSFER => true ]); $resp = curl_exec($ch); if ($resp === false) { do_action( 'qqworld-collector-log', $this->log_id, 'ctfile request failed:', curl_error($ch) ); curl_close($ch); return false; } curl_close($ch); return json_decode($resp, true); } public function is_object_exist($destination_path) { $destination_path = preg_replace('/^\/*/i', '', $destination_path); $this->access_service(); $path = trim($destination_path, '/'); if ($path === '') { return false; } $parts = explode('/', $path); $fileName = array_pop($parts); $folderId = $this->resolveFolderIdByPath($parts, 'd0'); if ($folderId === null) { return false; } return $this->fileExistsInFolder($folderId, $fileName); } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; $destination_path = preg_replace('/^\//', '', $destination_path); $this->access_service(); if ($this->is_object_exist($destination_path)) { $this->delete_object($destination_path); } $path = dirname($destination_path); $folderId = $this->createPath($path); $filePath = $source_path; $customName = null; $prep = $this->getUploadUrl($folderId, $filePath, $customName); if ((int)$prep['exists'] === 1) { return ['exists' => 1, 'message' => 'server already has the file']; return false; } if (empty($prep['upload_url'])) { do_action( 'qqworld-collector-log', $this->log_id, 'ctfile invalid upload_url:', $destination_path ); return false; } $data = $this->uploadToUploadUrl($prep['upload_url'], $filePath, $prep['name'], $prep['size']); $this->error_log($data); if ($data['code'] == 200) { $data = $this->getShareLinks(['f'.$data['id']]); if ($data['code'] == 200) { return $data['results'][0]['drlink']; } } return false; } public function delete_object($object) { $object = preg_replace('/^\/*/i', '', $object); $this->access_service(); $deleteRes = $this->deleteToRecycle([$fileId]); $clearRes = $this->clearRecycleByIds([$fileId]); return true; } public function add_form_fields() { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage3.php'; } public function add_could_storage_form($guid) { $this->access_service(); require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } } ?>